local zones = {
	[947] = {
		name = "Azeroth",
		short = "Ten thousand years ago the Highborne of Kalimdor, drunk on the power of the Well of Eternity, answered the call of the fallen titan Sargeras and tore open a gate for the Burning Legion.",
		full = "Ten thousand years ago the Highborne of Kalimdor, drunk on the power of the Well of Eternity, answered the call of the fallen titan Sargeras and tore open a gate for the Burning Legion. Malfurion Stormrage and the Kaldorei resistance shattered that gate with the Dragon Soul and hurled Sargeras back into the Twisting Nether, but the Well's collapse broke the world itself. Ancient Kalimdor sank in fire and flood; ruined continents rose from the wreck, and the drowned heart of the land became the Great Sea, with the Maelstrom churning where the Well once stood.",
		source = "https://warcraft.wiki.gg/wiki/Azeroth",
	},
	[1411] = {
		name = "Durotar",
		short = "Durotar is a cracked, red land of crags and canyons, dry and hot, sparse in water and green things.",
		full = "Durotar is a cracked, red land of crags and canyons, dry and hot, sparse in water and green things. Orcs find in it a harsh beauty that recalls Draenor, and it is here, after Mount Hyjal, that Thrall led his people to build a new homeland, naming it for his murdered father Durotan. The land had belonged to the Razormane quilboar before the Horde drove them off.\n\nThat peace did not hold long. Grand Admiral Daelin Proudmoore, a hero of the Second War and no friend to orcs, brought a great Alliance fleet against Durotar, determined to crush the Horde before it could take root. His daughter Jaina chose otherwise: at Theramore she turned against her own father to fight beside Thrall, and Daelin died in the battle before the two could ever reconcile. In gratitude for her loyalty, Thrall let Jaina's soldiers withdraw to Theramore unharmed.\n\nThe Darkspear trolls came to Durotar's coast as exiles, not settlers by choice. Betrayed by one of their own, the sorcerer Zalazane, they were driven from their home in the Echo Isles and built the fishing village of Sen'jin on the mainland shore, never able to reclaim what Zalazane had taken.",
		source = "https://warcraft.wiki.gg/wiki/Durotar_(Classic)",
	},
	[1412] = {
		name = "Mulgore",
		short = "For hundreds of years the tauren had no land of their own, driven across Kalimdor by centaur raiders who scattered their tribes into wandering camps.",
		full = "For hundreds of years the tauren had no land of their own, driven across Kalimdor by centaur raiders who scattered their tribes into wandering camps. When Thrall and his orcs landed on these shores, Cairne Bloodhoof looked upon them and saw kindred spirits, honorable and strong. With the orcs' escort and their strength at his back, Cairne led his people into the sheltered valley walled in by mountains on every side, and there his Bloodhoof tribe drove the centaur from the grasslands and claimed them at last.\n\nUpon the mesa that rose above the plain, Cairne built Thunder Bluff, a refuge open to tauren of every tribe, and in time the scattered peoples united under his rule.\n\nThe pastures remain green, the mesas still cast their long shadows over Bloodhoof Village, and every tauren who comes of age must still walk into the wild plains to prove themselves in the Great Hunt, as their ancestors did.",
		source = "https://warcraft.wiki.gg/wiki/Mulgore_(Classic)",
	},
	[1413] = {
		name = "The Barrens",
		short = "The dust here was not always dust. Once this was forest, tended by kaldorei who raised the outpost of Then'Ralore, and it is said the demigod Lo'Gosh stood here against the Burning Legion in the War of the Ancients.",
		full = "The dust here was not always dust. Once this was forest, tended by kaldorei who raised the outpost of Then'Ralore, and it is said the demigod Lo'Gosh stood here against the Burning Legion in the War of the Ancients. The Great Sundering ended all that, and the green valley became the sun-scorched plain it is now.\n\nFor generations the tauren wandered these plains, hunting kodo and thunder lizard, seeking the Earth Mother's wisdom, forever hounded by centaur who hunted them for sport. They fought back but never for love of war; when the horse-men came, they struck their tents and moved on rather than throw lives away. A year of peace, a year of war -- that was tauren life, until Thrall's orcs and the Darkspear trolls landed and marched with the Bloodhoof tauren against the centaur. After the Legion's fall at Mount Hyjal, Thrall claimed the eastern Barrens, drove off the Razormane quilboar, and named that land Durotar, raising Orgrimmar as its capital.\n\nThe land holds older griefs too: it is said a man named Dethorin found his love Allurana in another's arms, and his cry tore the axe Killmaim up out of the sand -- the same blade he used to kill her.",
		source = "https://warcraft.wiki.gg/wiki/Barrens_(Classic)",
	},
	[1414] = {
		name = "Kalimdor",
		short = "After the Sundering broke the world, the night elves who remained withdrew deliberately from the rest of the world.",
		full = "After the Sundering broke the world, the night elves who remained withdrew deliberately from the rest of the world. Among humans, Kalimdor survived only as legend, a land said to have broken and sunk beneath the waves, without location or shape known to them.\n\nBut it was not entirely lost. Night elves visited the quel'dorei in the years that followed, and so the high elves of Quel'Thalas alone knew the legend was true.\n\nEven when the Third War came, most humans still refused to believe Kalimdor existed, the Kirin Tor's own ambassador to King Terenas' court among the doubters. Only a few heeded Medivh's warning and sailed west, Thrall's new Horde among them, Jaina Proudmoore's expedition following. What they found was no legend but a whole continent, ice in its north, desert in its south, and night elves still holding the woods between.",
		source = "https://warcraft.wiki.gg/wiki/Kalimdor",
	},
	[1415] = {
		name = "Eastern Kingdoms",
		short = "The Eastern Kingdoms were not always many lands.",
		full = "The Eastern Kingdoms were not always many lands. Once they were part of a single continent, before the Great Sundering tore the world apart and left behind the broken pieces now called Azeroth, Khaz Modan, and Lordaeron, with Quel'Thalas clinging to the north of that last shattered land, uncertain even now whether it stands as its own place or merely a corner of another.\n\nAcross these fragments the mountains of Khaz Modan and the Redridge rise like a spine through the continent's heart, and around them the old peoples endure: dwarves and gnomes in their deep halls, humans in their kingdoms, high elves in their woods, and now the Forsaken risen where Lordaeron's people once lived. Orcs, goblins, naga, and ogres have all found their way into these lands as well, though none of them were born to it.\n\nThe scars of that first breaking are still the truth of the place. Every border here, every strait and stretch of drowned ground between one kingdom and the next, remembers that the Eastern Kingdoms were once whole, and are whole no longer.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Kingdoms",
	},
	[1416] = {
		name = "Alterac Mountains",
		short = "Rain never quite stops falling on these peaks, and the sky above them is always grey. Once the mountains crowned the city-state of Alterac, which held dominion over much of the northlands, and sheltered Dalaran besides.",
		full = "Rain never quite stops falling on these peaks, and the sky above them is always grey. Once the mountains crowned the city-state of Alterac, which held dominion over much of the northlands, and sheltered Dalaran besides. Both are gone now, and what is left explains why so few dare climb here.\n\nWhen the Second War ended, the Alliance of Lordaeron learned that Alterac's lords had dealt with the Horde in secret, and marched an army into these mountains to strike the traitors at their own hearth. The city fell, its people scattered or imprisoned, and its bloodline never recovered its throne. A later prince of that fallen house, Aliden Perenolde, rose instead as a bandit lord, gathering the outcast and the vengeful into the Syndicate, a company of rogues who still hold Strahnbrad and range across these slopes seeking to reclaim what his family lost.\n\nToday the ruins of Alterac City belong to the Crushridge ogres, and the Syndicate holds much of what the ogres do not.",
		source = "https://warcraft.wiki.gg/wiki/Alterac_Mountains_(Classic)",
	},
	[1417] = {
		name = "Arathi Highlands",
		short = "King Thoradin came to this arid country because a dream told him his people would prosper here, and he raised Strom upon it, the first capital of a united Arathor.",
		full = "King Thoradin came to this arid country because a dream told him his people would prosper here, and he raised Strom upon it, the first capital of a united Arathor. The dry ground served him as a wall of thorns, denying the forest trolls of Amani the cover for their ambushes, and he raised a second wall besides. For a thousand years Strom stood at the heart of the empire, until its noble houses drifted away to richer soil and Thoradin's last descendants left to found Stormwind. What remained became Stromgarde, held ever after by the Trollbane line.\n\nStromgarde has since fallen, overrun by ogres and the Syndicate, its survivors driven from the keep to a canyon they now call Refuge Pointe. Nearby stands Hammerfall, once a camp where humanity caged its orcish prisoners, now held by the orcs themselves and renamed for Orgrim Doomhammer.\n\nThoradin's great wall has collapsed into a gaping ruin, and his keep lies broken and contested, fought over still by the ogres, the Syndicate, and the last soldiers of a kingdom trying to reclaim it.",
		source = "https://warcraft.wiki.gg/wiki/Arathi_Highlands_(Classic)",
	},
	[1418] = {
		name = "Badlands",
		short = "The Badlands is a cracked desert of dry earth, scattered boulders, and winding canyons, hemmed in by mountains on every side. Little survives here but coyotes, cougars, and buzzards.",
		full = "The Badlands is a cracked desert of dry earth, scattered boulders, and winding canyons, hemmed in by mountains on every side. Little survives here but coyotes, cougars, and buzzards.\n\nIn the northern reaches lie the ruins of Uldaman, workings of the ancient earthen. When it was unearthed, it offered the first clues to the dwarves' lofty origins, and Ironforge prospectors flooded in to search the ruin for Titan artifacts. But the Stonevault troggs, roused after millennia of slumber, slaughtered the explorers and now defend their stolen city with savage purpose. A large Dark Iron fortress stands just south of Uldaman, its dwarves warring with the ogres of the Dustbelcher tribe and the drakes that nest among the black dragon spawn in the east.\n\nLater, Kargath was founded here as the only Horde outpost in Khaz Modan, raised so orcs might watch their renegade Blackrock kin. Warchief Thrall himself sent the Kargath Expeditionary Force to hunt down Rend Blackhand.",
		source = "https://warcraft.wiki.gg/wiki/Badlands_(Classic)",
	},
	[1419] = {
		name = "Blasted Lands",
		short = "The Blasted Lands take their name honestly. The red clay underfoot was once tan earth, part of a dark marsh called the Black Morass, before the Orcish Horde tore the Dark Portal open here and poured into Azeroth.",
		full = "The Blasted Lands take their name honestly. The red clay underfoot was once tan earth, part of a dark marsh called the Black Morass, before the Orcish Horde tore the Dark Portal open here and poured into Azeroth. What magic leaked through that day scorched the soil red and killed it for good. Nothing grows here now but hardy desert scrub, and hardy desert things: basilisks, scorpions, hyenas.\n\nArchmage Khadgar and the Kirin Tor raised Nethergarde Keep to watch the ruin of the gateway and see that nothing came through it again. Peace held for two years, until the Horde of Draenor reopened the Portal and besieged the keep. When Ner'zhul's ritual began tearing Draenor apart, Khadgar and the other magi used the Skull of Gul'dan to blast the Portal's stone frame to pieces from the far side, severing the bridge between the worlds for good.\n\nToday Nethergarde's mages and paladins still keep their grim watch over the dead Portal, a tight, humorless community that trusts no one and forgives no lapse, the only shelter to be found in a land where the storms off the eastern sea run off the baked ground before they can do any good.",
		source = "https://warcraft.wiki.gg/wiki/Blasted_Lands_(Classic)",
	},
	[1420] = {
		name = "Tirisfal Glades",
		short = "The sky over Tirisfal Glades has hung sickly green for years, the trees clinging to whatever life the plague left them.",
		full = "The sky over Tirisfal Glades has hung sickly green for years, the trees clinging to whatever life the plague left them. Once these were peaceful farms under King Terenas, generations living quietly among the mills and pumpkin fields. That ended when Arthas Menethil ransacked Lordaeron and swept the plague through the countryside, killing its people and raising them as slaves to the Lich King. Mass graves still mark where the dead were too numerous to bury properly. It was near the Balnir Farmstead, months later, that Sylvanas Windrunner turned her banshees against Arthas and put a poisoned arrow in the death knight before Kel'Thuzad's skeletons drove her off.\n\nOut of that ruin came the Forsaken, Sylvanas's free-willed dead, who claimed the land as their own. Their enemies never left it: the Scarlet Crusade holds the old Scarlet Monastery in the north, fanatics who burn and hunt anything not human.",
		source = "https://warcraft.wiki.gg/wiki/Tirisfal_Glades_(Classic)",
	},
	[1421] = {
		name = "Silverpine Forest",
		short = "Silverpine Forest, or simply Silverpine, is a vast, ancient wood that runs along Lordaeron's rugged western coast. The land ranges from fairly flat to hilly, and is nestled among even taller mountains.",
		full = "Silverpine Forest, or simply Silverpine, is a vast, ancient wood that runs along Lordaeron's rugged western coast. The land ranges from fairly flat to hilly, and is nestled among even taller mountains. The forest is eerily silent save for the occasional unnatural howling echoing among the trees. Mossy overhangs shiver in the cold breeze, and the trees are all sickly or dying. Dilapidated farmsteads and abandoned mines dot the land, home now to the darker denizens of the woods.\n\nThis woodland is haunted and wild, characterized by its tall, silver-barked pines towering over grassy knolls. The Alliance once protected Silverpine Forest when it was verdant and lively. Now the place is shrouded in ghostly mists. Forsaken control the northern forest and constantly clash with the wretched Rot Hide gnolls. What remains of the human population retains control of the southern forest, but they are desperate and their forces thinly stretched. Dalaran sends frequent expeditions into Silverpine to defend these people and study the undead plague and worgen curse -- a mysterious affliction that causes its victims to transform into bloodthirsty, lycanthropic worgen when the moon rises.\n\nGilneas and the Hillsbrad Foothills border the forest to the south, while Tirisfal Glades lays to the north. Lordamere Lake serves as Silverpine's eastern border.\n\nThough the territory belongs to the Forsaken, their claim is disputed by the wizards of Dalaran and agents of the Scourge who have taken possession of some of the ruined fields and steadings. Rothide gnolls operate from the mysterious Fenris Isle, and fiercely attack anyone who dares approach their dealings. In the southwest lays Pyrewood Village, whose people have fallen under archmage Arugal's curse, transforming into bloodthirsty worgen at night-time. Arugal makes his home in the nearby darkened towers of Shadowfang Keep.\n\nSilverpine Forest frequently sees battle, as Alliance forces from Southshore journey to the forsaken woods to attack the Sepulcher or enter Shadowfang. It is the edge of the Forsaken homeland, and the southernmost point where effects of the undead plague can be seen in the plant life.",
		source = "https://warcraft.wiki.gg/wiki/Silverpine_Forest_(Classic)",
	},
	[1422] = {
		name = "Western Plaguelands",
		short = "Once these were the fairest farmlands of northern Lordaeron, forested and green, feeding the kingdom's granaries from Andorhal and governed from the hall at Hearthglen.",
		full = "Once these were the fairest farmlands of northern Lordaeron, forested and green, feeding the kingdom's granaries from Andorhal and governed from the hall at Hearthglen. That prosperity became the weapon used to destroy it.\n\nActing on the Lich King's design, the Cult of the Damned carried his plague energies south in portable cauldrons, hiding them in loyal cultist villages and setting the largest four in Andorhal's own fields. The grain itself was tainted, and it went out across Lordaeron in wagons nobody thought to question. The people who ate their own bread sickened, died, and rose again as the Lich King's slaves. The forests never recovered. The pines stand grey and needled brown under a haze of sickly mist, their trunks swollen with tumorous growths.\n\nWhat order remains was salvaged after the kingdom's collapse, when the Scarlet Crusade seized Mardenholde Keep at Hearthglen and struck out from there against the undead holding the rest of the land. Amid it all only one place keeps any peace: Uther's Tomb, consecrated to Uther Lightbringer, ground the blight has never touched.",
		source = "https://warcraft.wiki.gg/wiki/Western_Plaguelands_(Classic)",
	},
	[1423] = {
		name = "Eastern Plaguelands",
		short = "The ground here was farmland once, the villages of Eastweald scattered around Stratholme, second city of Lordaeron. None of that remains.",
		full = "The ground here was farmland once, the villages of Eastweald scattered around Stratholme, second city of Lordaeron. None of that remains. The soil is brown and sick now, the trees swollen into mushrooms, the air thick with orange mist.\n\nIt was at Stratholme that Prince Arthas came, hunting the source of a plague that had already claimed the townsfolk. Lord Uther, master of the Silver Hand, refused to let him purge the city. Arthas stripped him of command, disbanded the Silver Hand on the spot, and put the people of Stratholme to the sword himself rather than let them rise as the Scourge's own. He did not stop there -- he hunted the dreadlord Mal'Ganis into the north, returned a death knight, and killed his own father to end the kingdom of Lordaeron.\n\nAlexandros Mograine raised a Crusade from the Silver Hand's remnant to take the ruin back, seizing Tyr's Hand and half of Stratholme before his death broke his order into the Argent Dawn and the Scarlet Crusade that still holds these fields, warring the Scourge without end and welcoming no one else.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Plaguelands_(Classic)",
	},
	[1424] = {
		name = "Hillsbrad Foothills",
		short = "Hillsbrad's soil is rich and its hills green, and travelers say it is what all of Lordaeron looked like before the Plague came.",
		full = "Hillsbrad's soil is rich and its hills green, and travelers say it is what all of Lordaeron looked like before the Plague came. That is its cruelty as much as its comfort: the land remembers what was lost everywhere else, while the people who hold it fight the same war that ruined the rest.\n\nAt the outset of the Second War, orcish raiders struck its coastal towns, and Orgrim Doomhammer himself rode against Durnholde Keep to free Zul'jin from its cells. Decades later it was Thrall who came through these hills, gathering the scattered orcish clans before slipping into Southshore by night to steal its ships and carry the new Horde across the sea to Kalimdor.\n\nWhat the orcs began, the Forsaken have continued. They claimed Tarren Mill as their southernmost holding and turned it into a staging ground against the humans of Southshore and Hillsbrad Fields, who held fast for the Alliance.\n\nPine woods dot the farmland now, and roads still cross the pastures toward the gloomy Forsaken settlements to the north, as if the land itself were still waiting to see which side keeps it.",
		source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Foothills_(Classic)",
	},
	[1425] = {
		name = "The Hinterlands",
		short = "After the War of the Three Hammers, the Wildhammer dwarves abandoned their tunnels at Grim Batol and came north, building their homes above ground at Aerie Peak.",
		full = "After the War of the Three Hammers, the Wildhammer dwarves abandoned their tunnels at Grim Batol and came north, building their homes above ground at Aerie Peak. They turned from stone and forge toward sky and wing, binding themselves to the wild gryphons of the region so closely that they raised a great stone gryphon in their own city to honor the bond. The forest trolls who already held this land, remnants of the once-great Amani Empire, saw the dwarves as squatters on ancestral ground and raided the aeries whenever they could.\n\nWhen the Horde swept through during the Second War, Thane Kurdran Wildhammer and his riders, until then unaware such invaders even existed, fell on the orc columns from the sky with storm-touched hammers, hounding them without pause. Orgrim Doomhammer hoped to draw the Alliance's strength into the Hinterlands so he might strike Quel'Thalas unopposed, but Anduin Lothar saw the plan and rode to Kurdran's side himself, and together they broke the invaders and drove them back to the Alterac Mountains. For that, Kurdran pledged his people's aid to the Alliance.",
		source = "https://warcraft.wiki.gg/wiki/Hinterlands_(Classic)",
	},
	[1426] = {
		name = "Dun Morogh",
		short = "Snow lies deep across Dun Morogh, walled in on every side by the Khaz Modan mountains, its passes watched always by dwarven troops.",
		full = "Snow lies deep across Dun Morogh, walled in on every side by the Khaz Modan mountains, its passes watched always by dwarven troops. Before the mountains belonged to anyone else, they belonged to the Frostmane ice trolls, who had settled the region after breaking away from the Drakkari Empire in ages past.\n\nThat changed when the first gnomes climbed out of Uldaman and turned their wits toward surviving the cold and the trolls alike, digging fortified dwellings deep into the peaks. Five hundred years later the dwarves followed them up out of Uldaman, drawn by the same mountains they had glimpsed on the horizon, and raised Ironforge beneath the tallest of them. Finding the gnomes already settled nearby, the two peoples struck a friendship that has never broken: the dwarves lending their strength to raise Gnomeregan, the gnomes sharing the secrets of their machines. Together their armies broke the Frostmane trolls and drove the survivors back into the hills, ending the trolls' hold on the land for good.\n\nGnomeregan is gone now, ruined, and its people crowd into Ironforge for shelter.",
		source = "https://warcraft.wiki.gg/wiki/Dun_Morogh_(Classic)",
	},
	[1427] = {
		name = "Searing Gorge",
		short = "Once this was green land, part of the Redridge Mountains, until the ground itself was torn open more than two hundred and thirty years ago.",
		full = "Once this was green land, part of the Redridge Mountains, until the ground itself was torn open more than two hundred and thirty years ago.\n\nIn the War of the Three Hammers, Sorcerer-Thane Thaurissan of the Dark Iron dwarves sought a weapon to break his enemies. He and seven of his most trusted dwarves reached beneath the world and called upon powers that should have stayed sleeping. What answered was not a servant but a master: the ancient Firelord Ragnaros. His waking tore Blackrock Mountain up out of the earth, blackened the land for miles, and crushed the Dark Iron capital of Thaurissan to rubble beneath it. The scorched steppes to the south became known as the Burning Steppes; this ravaged valley to the north became the Searing Gorge.\n\nNot all Dark Irons stayed loyal to their clan after the ruin. A number of them broke away, calling themselves the Thorium Brotherhood, and built Thorium Point overlooking the great excavation their former kin had driven into the valley floor, watching the Dark Irons' labors from above.",
		source = "https://warcraft.wiki.gg/wiki/Searing_Gorge_(Classic)",
	},
	[1428] = {
		name = "Burning Steppes",
		short = "The sky over the Burning Steppes never loses its red hue, lit by sporadic eruptions from Blackrock Mountain, and the ground never cools.",
		full = "The sky over the Burning Steppes never loses its red hue, lit by sporadic eruptions from Blackrock Mountain, and the ground never cools. Two hundred years before the Dark Portal opened, Dark Iron dwarves came here in exile from Ironforge. Their Sorcerer-Thane, Thaurissan, sought to summon elemental minions to win the War of the Three Hammers against the Bronzebeard and Wildhammer clans. What answered was not a minion but Ragnaros the Firelord, once banished by the titans. His arrival melted the mountains around him, raised a volcano at the blast's heart, and destroyed the dwarves who had summoned him. What lay north of that new peak became the Searing Gorge; what lay south, the Burning Steppes, scarred ever since.\n\nOrcs settled the volcano's slopes during the First War and held Blackrock Spire as a stronghold through the Second. The Blackrock orcs returned afterward and remain there still, following the old brutal ways from before Thrall's truce. Black dragons under Nefarian hold the spire's upper levels, and it is said Ragnaros yet broods somewhere beneath it all.",
		source = "https://warcraft.wiki.gg/wiki/Burning_Steppes_(Classic)",
	},
	[1429] = {
		name = "Elwynn Forest",
		short = "When the orcs came in the First War, thousands marched through Elwynn to surround Stormwind, cutting it off from everything but the sea.",
		full = "When the orcs came in the First War, thousands marched through Elwynn to surround Stormwind, cutting it off from everything but the sea. Knight Champion Anduin Lothar led the Knights of Stormwind in a charge through the forest itself, striking the orcish rearguard by surprise and scattering them. It bought the city time, but not enough. Warchief Blackhand soon took Goldshire and Moonbrook, the last towns standing between the Horde and the king, and Stormwind Keep was sacked. Lothar led the survivors to the sea and away to Lordaeron, and the ruins of the city belonged for a time to the Stormreaver clan. Scattered orcish catapults still lie broken and rotting across the region, the only reminders left of that occupation.\n\nNorthshire Vineyards, east of the city, were once the pride of Stormwind's farmers. When the Stonemasons Guild went unpaid for the years they spent rebuilding the ruined capital, and the nobles disbanded them rather than settle the debt, Guildmaster Edwin VanCleef's fury spread into riots that killed Queen Tiffin Ellerian Wrynn and birthed the Defias Brotherhood. The Brotherhood drove the farmers from Northshire and occupied its fields.",
		source = "https://warcraft.wiki.gg/wiki/Elwynn_Forest_(Classic)",
	},
	[1430] = {
		name = "Deadwind Pass",
		short = "Deadwind Pass cuts through the mountains of central Azeroth, joining Duskwood to the Swamp of Sorrows. A score of years ago it was counted part of the Redridge Mountains.",
		full = "Deadwind Pass cuts through the mountains of central Azeroth, joining Duskwood to the Swamp of Sorrows. A score of years ago it was counted part of the Redridge Mountains.\n\nThe Ivory Tower of Karazhan, once the dark wizard Medivh's seat of power, stands at the center of this jagged region and leaks evil magic into the land. The trees are petrified and leafless, and a terrible wind keens through the canyon. Ogres, demons, undead and a few human gypsies roam the interior -- and whispers tell that a new force has claimed the Ivory Tower, and that the ogres and demons are under its sway.",
		source = "https://warcraft.wiki.gg/wiki/Deadwind_Pass_(Classic)",
	},
	[1431] = {
		name = "Duskwood",
		short = "A blanket of unnatural night lies over Duskwood, and it has never lifted.",
		full = "A blanket of unnatural night lies over Duskwood, and it has never lifted. What was once a fair stretch of Elwynn Forest is now a cursed, dying land: the trees grew gnarled beneath the black fog, the dead rose from their graves, and worgen came slinking in with the darkness itself, drawn by the workings of the Scythe of Elune. Ogres pressing in from Deadwind Pass have only deepened the misery.\n\nStormwind's protection long ago ceased to mean anything here, and the people who remain have learned to hold their ground without it. Their militia, the Night Watch, patrols the roads and guards Darkshire against whatever moves in the shadows -- skeletal warriors and ghouls, ferocious worgen, and Defias men besides.\n\nAt the wood's heart lies the crater of a long-dead volcano, cloaked in a twilight gentler than the dark around it. Within it stands one of the Great Trees, its roots reaching toward the Emerald Dream, and the sleeping druids' influence colors everything that grows nearby. Beyond it stretch abandoned farmsteads and the sprawling graves of Raven Hill Cemetery, filled year by year since the darkness fell.",
		source = "https://warcraft.wiki.gg/wiki/Duskwood_(Classic)",
	},
	[1432] = {
		name = "Loch Modan",
		short = "The waters of Loch Modan lie cradled in gray stone, held by the Stonewrought Dam, a work of dwarven engineering that no other structure on Azeroth has ever equaled.",
		full = "The waters of Loch Modan lie cradled in gray stone, held by the Stonewrought Dam, a work of dwarven engineering that no other structure on Azeroth has ever equaled. The mountains rise sheer on every side, lightly wooded with pine and birch, and the loch itself sits still and quiet, as though nothing had ever disturbed it.\n\nThe loch was a battlefield once. In the Second War the orcs of the Horde swept into the region and made their stand here against the Alliance. Ironforge held. Its dwarves threw the orcs back and reclaimed Loch Modan, and the wreckage of that war was never fully cleared: broken catapults and shattered ballistae still lie scattered across the lakebed and its islands, half-sunk, the only proof left that this calm water was ever a killing ground.",
		source = "https://warcraft.wiki.gg/wiki/Loch_Modan_(Classic)",
	},
	[1433] = {
		name = "Redridge Mountains",
		short = "The Redridge Mountains lie east of Elwynn Forest, northeast of Duskwood, and south of the Burning Steppes.",
		full = "The Redridge Mountains lie east of Elwynn Forest, northeast of Duskwood, and south of the Burning Steppes.\n\nAn idyllic region of rushing rivers, towering elms, and rising elevation, Redridge stands under Stormwind's protection, though since the Second War it has been technically independent. It remains one of the last peaceful regions of Azeroth, its people calm and content, supplying Stormwind with timber, fish, and crops. Yet the peace is imperfect: a force of Blackrock orcs from the Burning Steppes holds Stonewatch Keep, though so far they keep to themselves. Compared to the ruin of Westfall, Redridge still holds together.\n\nOn the northern bank of Lake Everstill stands the town of Lakeshire, besieged by gnolls and Blackrock orcs out of the surrounding hills. To its south, the crossroads known as the Three Corners links Lakeshire to Elwynn and Duskwood, and by the Lakeridge Highway to Stonewatch Keep, a road held by dragon whelps, gnolls, murlocs, and wild beasts.\n\nThe lake's surface looks calm enough, but murlocs lurk beneath it, and rumors persist of a sea monster in its depths.",
		source = "https://warcraft.wiki.gg/wiki/Redridge_Mountains_(Classic)",
	},
	[1434] = {
		name = "Stranglethorn Vale",
		short = "Stranglethorn Vale is a vast jungle south of Duskwood. Jungle trolls patrol this steaming rainforest, and naga hunt along its coasts, while stranglethorn vines and beasts make travel dangerous.",
		full = "Stranglethorn Vale is a vast jungle south of Duskwood. Jungle trolls patrol this steaming rainforest, and naga hunt along its coasts, while stranglethorn vines and beasts make travel dangerous.\n\nThe vale was once the heart of the Gurubashi Empire, whose great cities stood throughout the region. After the empire's fall, those cities crumbled into ruin, though trolls still dwell among them. Zul'Gurub, in the northeast, was once the Gurubashi capital.\n\nBooty Bay was originally a small port town settled by humans, until it was overrun by trolls. The goblins of the Steamwheedle Cartel later drove the trolls from the cove and claimed it for their own, building it into their center of operations in the Eastern Kingdoms.\n\nIn the north stands a compound raised by Colonel Kurzen's expedition. There the colonel's mind was seized by an ogre mage, Mai'Zoth, who used an artifact called the Mind's Eye to bend Kurzen's will and command his men. A number of Kurzen's soldiers rebelled against their possessed commander and fled west, founding a rebel camp in defiance of him.",
		source = "https://warcraft.wiki.gg/wiki/Stranglethorn_Vale_(Classic)",
	},
	[1435] = {
		name = "Swamp of Sorrows",
		short = "Beneath the black water of the swamp lies a temple older than the sorrow that named this place.",
		full = "Beneath the black water of the swamp lies a temple older than the sorrow that named this place. When the Gurubashi Empire fell, a renegade band of trolls called the Atal'ai fled into the marsh and raised the Temple of Atal'Hakkar, where they practiced grisly rites to summon their dark loa, Hakkar the Soulflayer, back into the world. Their magic twisted the plants and beasts around the temple until the corruption could not go unnoticed. Ysera, mistress of dreams, learned of the cult's ambitions and turned her power against them, drowning the temple beneath the largest bog before Hakkar could return. But she did not trust the trolls to abandon their god forever. She set her consort Eranikus and a host of green dragons to keep eternal watch over the ruin, so it might never again be used to loose such evil upon the world. Green dragonspawn still patrol these marshes at her command, and the sunken temple remains sealed beneath the water, watched rather than destroyed.",
		source = "https://warcraft.wiki.gg/wiki/Swamp_of_Sorrows_(Classic)",
	},
	[1436] = {
		name = "Westfall",
		short = "The wind runs unbroken over Westfall's fields now, for nothing tall remains to break it. Once this was the breadbasket of Stormwind, feeding the young kingdom for generations.",
		full = "The wind runs unbroken over Westfall's fields now, for nothing tall remains to break it. Once this was the breadbasket of Stormwind, feeding the young kingdom for generations.\n\nWhen the Stonemasons Guild went unpaid for rebuilding Stormwind after the Second War, and the guard turned against their protests, Guildmaster Edwin VanCleef led his men into hiding in the countryside rather than face King Varian's justice. There they became the Defias Brotherhood, and beneath a barn in Moonbrook, VanCleef found an old mining network deep enough to hide the building of a weapon meant to burn Stormwind from the sea. He drove off the farmers, hired Riverpaw gnolls to hold the land, and had his men burn the fields and salt the earth so nothing would grow there again.\n\nStormwind, its coffers spent, left Westfall to fend for itself. Only Gryan Stoutmantle answered, raising the People's Militia at Sentinel Hill when no army came.\n\nThe fields he salted have not forgiven Westfall for it. The grass still grows yellow and thin where wheat once stood shoulder-high.",
		source = "https://warcraft.wiki.gg/wiki/Westfall_(Classic)",
	},
	[1437] = {
		name = "Wetlands",
		short = "A cold gray swamp lies below the dam, mist over its rivers and ponds, mountains hemming it in on three sides and the sea open to the west.",
		full = "A cold gray swamp lies below the dam, mist over its rivers and ponds, mountains hemming it in on three sides and the sea open to the west. Rubble is scattered through it, the remains of dwarven strongholds that once held this ground. Now murlocs, wild beasts, and renegade orcs hold it instead, and Menethil Harbor is the Alliance's only true foothold here.\n\nThat harbor was not always Alliance ground. When the Second War began, Orgrim Doomhammer built his invasion fleet on a small island in Baradin Bay, so his ships could strike at Lordaeron's shores without facing its ground defenses. The Wetlands paid for it: orcs and dragons fed heavily on the land, and game grew scarce. After the war the port was rebuilt and renamed Menethil Harbor, in honor of Terenas Menethil II.\n\nGrim Batol's fall came after. The red dragonflight, enslaved to serve the Dragonmaw clan there, turned on their captors once freed, and the clan was broken, its survivors scattered into the wild. Alexstrasza judged it her flight's burden to keep the mountain sealed, and red dragonkin have stood watch over it ever since.",
		source = "https://warcraft.wiki.gg/wiki/Wetlands_(Classic)",
	},
	[1438] = {
		name = "Teldrassil",
		short = "When Malfurion Stormrage vanished into the Emerald Dream, the archdruid Fandral Staghelm rose to lead the Cenarion Circle in his place and convinced the Circle of Ancients that the time had come to grow a new World Tree and win back the immortality the night elves had lost.",
		full = "When Malfurion Stormrage vanished into the Emerald Dream, the archdruid Fandral Staghelm rose to lead the Cenarion Circle in his place and convinced the Circle of Ancients that the time had come to grow a new World Tree and win back the immortality the night elves had lost. In the Veiled Sea they raised Teldrassil, crown of the earth, and built Darnassus in its boughs. But Nozdormu, who had blessed the first World Tree, refused this one, calling the wish arrogant, and the immortality the night elves sought never came.\n\nIn time the land atop Teldrassil fell under a sinister presence. Furbolgs and grell in its forests went mad, satyrs appeared among the trees, and the great turtles and threshers that once swam the waters around the tree fled to beach themselves and die on the shores of Darkshore. The source of this corruption remains a mystery, and Malfurion has not returned from the Dream to seek it out.",
		source = "https://warcraft.wiki.gg/wiki/Teldrassil_(Classic)",
	},
	[1439] = {
		name = "Darkshore",
		short = "A grey mist lies along this coast more often than not, and the night elves have long taken it as a warning.",
		full = "A grey mist lies along this coast more often than not, and the night elves have long taken it as a warning. Rain and rock make the land unwelcoming, and every attempt to settle it beyond the trading post of Auberdine has come to nothing.\n\nTen thousand years past, the twin cities of Ameth'Aran and Bashal'Aran stood here, ruled by Athrikus Narassin. When the War of the Ancients broke the world and the Great Sundering came on, Athrikus swore to his people that he would save them. He kept the letter of his promise and broke its spirit: he bound their souls into soul gems, telling them this was eternal life, while in truth he drained them to feed his own power. The cities fell to ruin, and what walks among the stones there now is not wholly at rest.\n\nAfter the Third War, Fandral Staghelm brought druids of the Cenarion Circle into Darkshore and planted a new World Tree, Teldrassil, upon this shore.",
		source = "https://warcraft.wiki.gg/wiki/Darkshore_(Classic)",
	},
	[1440] = {
		name = "Ashenvale",
		short = "Ashenvale is ancient forest, thick with old trees and old magic, and it has never stopped being fought over.",
		full = "Ashenvale is ancient forest, thick with old trees and old magic, and it has never stopped being fought over.\n\nThe orcs of the Warsong clan first came here as woodcutters. Goblins under Neeloc Greedyfingers stripped the trees until the local furbolgs drove them back, and Grommash Hellscream broke the furbolgs and the Sentinels in turn to keep the goblins' aid. Cenarius came himself to restore what had been felled, and it cost him his life: the Burning Legion's masters turned his trust into a trap, and Grommash struck him down.\n\nWorse followed when the Legion marched on Ashenvale in full. Archimonde's infernals fell burning from the sky, and undead and demons swept in from the east, overwhelming the divided armies of night elf, orc, and human alike before pressing on toward Mount Hyjal. Tyrande Whisperwind woke Malfurion from the Emerald Dream to find the forest he remembered consumed by fel fire and choking blight.\n\nThat old contest never ended. Night elves still hold Astranaar and their scattered refuges; the Horde has driven its Warsong camps deep into the south and east, cutting timber and pushing the Sentinels back. Neither side has ever finished the fight for these woods.",
		source = "https://warcraft.wiki.gg/wiki/Ashenvale_(Classic)",
	},
	[1441] = {
		name = "Thousand Needles",
		short = "The canyon runs deep and dry, its floor lost among towering mesas, until in the east it opens into the Shimmering Flats, a great salt pan under a wide sky.",
		full = "The canyon runs deep and dry, its floor lost among towering mesas, until in the east it opens into the Shimmering Flats, a great salt pan under a wide sky. The sunrise from Freewind Post or from the heights around Darkcloud Pinnacle is a spectacular thing to see over such barren country. The druid Quentin has wondered whether the harsh dryness here, set so close against the lush jungle of neighboring Feralas, is not a natural thing at all, but the mark of some strange magic worked upon the land.\n\nThe high mesas belong to the tauren, and Freewind Post stands as their hold among them. They did not keep this ground unchallenged. The local centaur pressed them, and worse, their own kin of the Grimtotem tribe turned against them, so that the tauren of Freewind Post were forced to fight tribe against tribe for the high country. Only with the aid of the Horde did they beat the centaur and the Grimtotem back.",
		source = "https://warcraft.wiki.gg/wiki/Thousand_Needles_(Classic)",
	},
	[1442] = {
		name = "Stonetalon Mountains",
		short = "Stonetalon Peak has always belonged to the spirits before it belonged to any people.",
		full = "Stonetalon Peak has always belonged to the spirits before it belonged to any people. The night elves keep a barrow and a glade at its crown, communing with nature, and the tauren hold it sacred too, for it was here the immortal Oracle once watched the strands of fate as the Earth Mother wove them. Legend says the first tauren to settle these mountains carried flaming totems up to the highest crags, lighting bonfires to An'she to burn back the darkness clinging to the stone.\n\nLower on the mountain, Elune long ago blessed a fountain with the gift of health. Harpies later took the peaks nearby, capturing the wyverns that nested there and fouling the fountain's waters. Thrall came against them, with Cairne Bloodhoof and his tauren at his side, breaking a band of centaur to win a Glyph of Purification and cleanse what the harpies had corrupted. The freed wyverns carried them up to the Peak itself.\n\nThat old peace with the land is gone in the south. The Venture Company has stripped Windshear Crag bare, felling its trees, choking the air with soot, and fouling the water with oil and waste, until the mountain spirits cried out loud enough for shaman as far as Orgrimmar to hear it.",
		source = "https://warcraft.wiki.gg/wiki/Stonetalon_Mountains_(Classic)",
	},
	[1443] = {
		name = "Desolace",
		short = "Theradras, daughter of Therazane the Stonemother, once lay slumbering beneath a fertile grassland.",
		full = "Theradras, daughter of Therazane the Stonemother, once lay slumbering beneath a fertile grassland. Tauren shaman, believing the Earth Mother herself dwelled below, called out to her for decades until at last something answered -- not the Earth Mother, but Theradras, roused in fury from her sleep. She fed on the land to restore her weakened form, and the meadows died in an instant. The tauren named what remained Desolace.\n\nZaetar, son of the forestlord Cenarius, came to bind her, but loved her instead, and she loved him back. Of their union the centaur were born, and their first act was to murder their own father. They multiplied swiftly and drove the tauren from the land, beginning centuries of war between the two races.\n\nTheradras dwells still in Maraudon, beneath the western canyons, and it is there that the centaur trace the birth of their race.",
		source = "https://warcraft.wiki.gg/wiki/Desolace_(Classic)",
	},
	[1444] = {
		name = "Feralas",
		short = "Feralas rises strange among its neighbors, a rainforest of ancient trees where the wastes around it promise only dust.",
		full = "Feralas rises strange among its neighbors, a rainforest of ancient trees where the wastes around it promise only dust. Scattered through its green stand the ruins of the elves, half swallowed by root and vine, greatest among them the buried city of Dire Maul.\n\nThe Gordunni ogres hold Feralas now, and they have made it theirs by breaking it. They have torn down whole stretches of forest, and their taint has settled over the land like a sickness. Beyond the walls of Dire Maul their raiding parties burn villages and murder travelers through the southern woods, a corruption spreading through the wilds that traces back to the ruins beneath.\n\nGrimtotem tauren live scattered through the region still, hunted by those who remember what the tribe has done.",
		source = "https://warcraft.wiki.gg/wiki/Feralas_(Classic)",
	},
	[1445] = {
		name = "Dustwallow Marsh",
		short = "The mosquitoes never stop here, and neither does the mud.",
		full = "The mosquitoes never stop here, and neither does the mud. Trees knot their fronds so thick over the water that sunlight comes down broken, and crocolisks and murlocs wait in the brackish shallows where the sea meets the swamp. In the south, black dragons gather in such numbers that folk simply call it the Wyrmbog.\n\nJaina Proudmoore made the first true home of this wilderness, leading her people here after the battle at Mount Hyjal to found Theramore on its rocky island. Her city's walls gleam, but they also contain her: beyond the scattered checkpoints on the road to the Barrens, the marsh remains as wild as ever, and her garrison has thinned with quiet desertions no one can explain.\n\nIt was here, too, that the peace between Horde and Alliance broke for good. Admiral Daelin Proudmoore brought the Kul Tiras fleet against the Horde in the marsh, and the skirmish that followed ended in his death, sealing the truce into open enmity.\n\nBrackenwall Village stands where the Stonemaul ogres opened their gates to the Horde. Beyond it the road to the Barrens lies empty and falling into disrepair, watched by nothing but the raptors and spiders that have always owned this ground.",
		source = "https://warcraft.wiki.gg/wiki/Dustwallow_Marsh_(Classic)",
	},
	[1446] = {
		name = "Tanaris",
		short = "Sand fills the place where a jungle used to stand. Before the world was broken, Tanaris was green, claimed as territory by the Gurubashi Empire.",
		full = "Sand fills the place where a jungle used to stand. Before the world was broken, Tanaris was green, claimed as territory by the Gurubashi Empire. When the Great Sundering tore the land apart, the jungle died and what was left baked into dune and stone. A tribe of trolls found themselves stranded here when the water receded, and over the long years that followed, their bodies and their ways bent to the desert until they were no longer the trolls they had been, but sand trolls, the Sandfury, a people made by the land that trapped them.\n\nThe goblins of the Steamwheedle Cartel chose this wasteland for their trade, founding Gadgetzan and Steamwheedle Port because the desert is as close to their sunken homeland as Kalimdor allows them to settle. The docks at Steamwheedle reach out toward the islands beyond, but the goblins keep their ships to themselves, unwilling to ferry any other race across the water.\n\nBeneath the dunes and the southern mountains, the tunnels run on for miles, largely unmapped, and those who go down do not always come back to say what they found.",
		source = "https://warcraft.wiki.gg/wiki/Tanaris_(Classic)",
	},
	[1447] = {
		name = "Azshara",
		short = "Autumn has held Azshara for ten thousand years, its trees burning orange and red above cliffs that drop into coral where a city still lies.",
		full = "Autumn has held Azshara for ten thousand years, its trees burning orange and red above cliffs that drop into coral where a city still lies. Azshara was once the greatest metropolis the night elves ever raised, and when the War of the Ancients came, most of it went into the sea. A few broken buildings still cling to the cliffside, staring down at their own ruins beneath the water.\n\nLong after, when Illidan Stormrage fled north from Mount Hyjal with his naga, mur'guls and satyrs in tow, he tore through Azshara's coast, wrecking the night elven harbors so that none could follow him to the Tomb of Sargeras. Maiev Shadowsong and her Watchers came behind him, putting down the maddened creatures he left in his wake.",
		source = "https://warcraft.wiki.gg/wiki/Azshara_(Classic)",
	},
	[1448] = {
		name = "Felwood",
		short = "The trees of Felwood do not grow so much as fester. Their bark weeps a sickly ichor, their leaves hang black and curling, and the wildlife beneath them comes twisted and hungry from the corruption in the soil.",
		full = "The trees of Felwood do not grow so much as fester. Their bark weeps a sickly ichor, their leaves hang black and curling, and the wildlife beneath them comes twisted and hungry from the corruption in the soil.\n\nThe rot was no accident of nature. As the Burning Legion pressed toward Mount Hyjal, Archimonde ordered the forest broken to weaken the night elves guarding the mountain, and the dreadlord Tichondrius carried out that order with a warlock relic of terrible power, the Skull of Gul'dan. The land answered by dying from the inside out: ancients turned rotten and violent, beasts mutated, the earth itself poisoned.\n\nIt was here that Illidan Stormrage made the choice that shaped the rest of his life. Told that the skull could be turned against the very corruption it had caused, Illidan went into Felwood alone, cut down Tichondrius, and claimed the relic for himself. He did not surrender it afterward. His hunger for magic proved stronger than caution, and for using the Legion's own power he was cast out by his own brother Malfurion.",
		source = "https://warcraft.wiki.gg/wiki/Felwood_(Classic)",
	},
	[1449] = {
		name = "Un'Goro Crater",
		short = "Un'Goro Crater lies walled off between three deserts, a wound of green sunk into the south of Kalimdor, where the world forgets to be barren.",
		full = "Un'Goro Crater lies walled off between three deserts, a wound of green sunk into the south of Kalimdor, where the world forgets to be barren. Dinosaurs older than memory move through its jungle, some grown to lengths no living thing should reach, and elementals of earth and fire walk untroubled among them. On the ridges above, pylons stand that no one has ever explained.\n\nDuring the War of the Shifting Sands, the night elves were driven back through this crater to the edge of the Tanaris desert, and there the Qiraji advance broke. Something in Un'Goro itself would not let the invaders take the land, though no one has said what.\n\nAn expedition led by Williden and Hol'anyee Marshal once tried to make a foothold here, but the savagery of the crater proved more than they had prepared for. Their camps were overrun, and the survivors fled to higher ground, making their stand at what is now called Marshal's Refuge.",
		source = "https://warcraft.wiki.gg/wiki/Un'Goro_Crater_(Classic)",
	},
	[1450] = {
		name = "Moonglade",
		short = "Moonglade lies cradled in a ring of mountains, a hidden vale where the forest has never known corruption.",
		full = "Moonglade lies cradled in a ring of mountains, a hidden vale where the forest has never known corruption. At its heart rests Lake Elune'ara, named for the goddess herself, and in the town of Nighthaven upon its shore, tauren and night elves walk together without quarrel, bound by a shared reverence for nature that the Moonglade Wardens will not see broken.\n\nIt was to this vale that Malfurion Stormrage came in the days of the War of the Ancients, when the night elves stood on the edge of ruin against the Legion. Malfurion knew his people could not win alone, and he led Tyrande Whisperwind and his brother Illidan into the sacred quiet of Moonglade to beg Cenarius for his aid. The demigod answered, and after the Great Sundering reshaped the world, the keepers of the grove and the dryads who had sheltered here went out into it. Cenarius himself never left, and Moonglade became the holiest ground of druidic worship.\n\nBeneath its countless mounds sleep the sanctums of druids past, and beneath Elune'ara's waters sleeps the demigod Omen, once beloved of Elune, his slumber uneasy.",
		source = "https://warcraft.wiki.gg/wiki/Moonglade",
	},
	[1451] = {
		name = "Silithus",
		short = "The desert lies at the far southwestern edge of Kalimdor, a waste of broken rock and sand reached by the wide path out of Un'Goro.",
		full = "The desert lies at the far southwestern edge of Kalimdor, a waste of broken rock and sand reached by the wide path out of Un'Goro. Beneath its surface lies the remnant of the Aqiri empire, Ahn'Qiraj, whose central temple the night elves sealed away in an effort to keep something terrible from waking. The ruins scattered across Silithus, and the silithid hives now riddling the sand, are proof enough that the sealing did not hold.\n\nLong ago the Qiraji themselves were driven behind the Scarab Wall, imprisoned there in the aftermath of the War of the Shifting Sands. Their servants, the silithid, were left free, and over the centuries they multiplied and spread across all of southern Kalimdor until the night elves judged the threat too great to watch any longer, and turned instead to reopening the Gates of Ahn'Qiraj to finish what the Wall had only delayed.\n\nThe Cenarion Circle keeps its watch from Cenarion Hold, tracking the silithid swarms and weighing whether they are a danger too great for any one people to face alone.",
		source = "https://warcraft.wiki.gg/wiki/Silithus_(Classic)",
	},
	[1452] = {
		name = "Winterspring",
		short = "Snow lies unbroken across Winterspring, its beauty undisturbed even where demons have overrun the southern reaches. It was once home to many of the blue dragonflight, among them Haleh, consort to Malygos.",
		full = "Snow lies unbroken across Winterspring, its beauty undisturbed even where demons have overrun the southern reaches. It was once home to many of the blue dragonflight, among them Haleh, consort to Malygos.\n\nTen thousand years ago the Highborne raised the city of Kel'Theril here, after stealing the Crystal of Zin-Malor from a temple in Eldarath. They could not resist testing its power, and when it shattered, the curse it loosed devoured them. The Great Sundering finished what the crystal began, and Kel'Theril fell to ruin. Its dead never left. Later, high elves came from Quel'Thalas seeking the crystal's shards, and the same madness took them. Now their ghosts walk the ruins beside the ones they came to study.\n\nGoblins hold Everlook in the valley's heart, and the night elves keep their own watch here still, guarding a homeland older than either of them.",
		source = "https://warcraft.wiki.gg/wiki/Winterspring_(Classic)",
	},
	[1453] = {
		name = "Stormwind City",
		short = "Stormwind rose in white stone after the Orcish Horde had burned it, raised by the Stonemasons' Guild under young King Varian.",
		full = "Stormwind rose in white stone after the Orcish Horde had burned it, raised by the Stonemasons' Guild under young King Varian. But when the crown's coffers ran dry from war debts, and the nobility refused the guild its wages, Guildmaster Edwin VanCleef's protest was answered with the guild's dissolution. Riots followed, and in the chaos Queen Tiffin Wrynn was killed. Varian's wrath drove the stonemasons into exile in Westfall, where they became the Defias Brotherhood -- while behind the throne, a councilor named Katrana Prestor quietly turned king against guild for her own ends.\n\nKing Varian has since gone missing under suspicious circumstances, and at Lady Prestor's urging the crown was given to his young son, Prince Anduin, to preserve order in the realm. Highlord Bolvar Fordragon serves as Regent of Stormwind and commander of its forces, while Lady Prestor advises him on the use of the kingdom's resources, unsuspected and unchallenged within the Keep.",
		source = "https://warcraft.wiki.gg/wiki/Stormwind_City",
	},
	[1454] = {
		name = "Orgrimmar",
		short = "Orgrimmar rose in the years after Mount Hyjal, when Warchief Thrall led his people to a desolate coast of Kalimdor.",
		full = "Orgrimmar rose in the years after Mount Hyjal, when Warchief Thrall led his people to a desolate coast of Kalimdor. He named the land Durotar for his father, and the city he raised there he named Orgrimmar, for Orgrim Doomhammer, the friend and mentor who had shaped him. It was built quickly but not carelessly: stout walls, massive gates, tall towers, with the mountains at its back carved into to form part of the fortress itself, so that the land stood guard over the city.\n\nThe Horde that built it was not the Horde that had once burned across the world. The demonic curse broken, Thrall's people turned from conquest toward survival, and Orgrimmar was raised as much by others as by orcs -- goblins, tauren, and Darkspear trolls labored alongside them, and the Mok'Nathal Rexxar lent his hand to the work. Centaur, harpies, thunder lizards, kobolds, and quilboar all tested the young city in its first years, but it endured, and became home not only to orcs but to trolls, tauren, and, in time, the Forsaken newly welcomed into the Horde.\n\nThe wind itself is no friend here: the razor-winds sweep through the valleys with enough force to tear the roofs from buildings raised without care.",
		source = "https://warcraft.wiki.gg/wiki/Orgrimmar",
	},
	[1455] = {
		name = "Ironforge",
		short = "Ironforge is the capital city of the dwarves, carved into the depths of Ironforge Mountain in northern Dun Morogh, ancestral home of the dwarves and one of the oldest cities on Azeroth.",
		full = "Ironforge is the capital city of the dwarves, carved into the depths of Ironforge Mountain in northern Dun Morogh, ancestral home of the dwarves and one of the oldest cities on Azeroth. It is the capital of Khaz Modan, ruled by King Magni Bronzebeard of the Bronzebeard clan.\n\nAn expansive underground city of craftsmen, explorers, miners, and warriors, famous for its industry and as an Alliance center of commerce, Ironforge is equal parts fortress and capital, a testament to the dwarves' strength and resilience. The city consists of concentric rings, smaller levels deeper underground, all radiating out from the namesake Great Forge at its center. It is full of small passageways, shops built into the rock walls, and cavernous rooms. The feel of the place is bustling, rowdy, and industrial, yet cozy; fires roar in the hearths of the inns and shops, and much dwarven laughing and frivolity is to be heard. Unlike Stormwind and Darnassus, the city is a massive cavern carved into the earth by the dwarves themselves; the ceiling and floor are both hard stone.",
		source = "https://warcraft.wiki.gg/wiki/Ironforge",
	},
	[1456] = {
		name = "Thunder Bluff",
		short = "Thunder Bluff rises on four windswept mesas above the grasslands of Mulgore, reached only by rope-and-wood elevators of tauren make, or by long bridges strung between the rises.",
		full = "Thunder Bluff rises on four windswept mesas above the grasslands of Mulgore, reached only by rope-and-wood elevators of tauren make, or by long bridges strung between the rises. Tents, longhouses, and painted totems crown each summit. For generations the tauren wandered as a nomadic people, harried without rest by the centaur who ranged across Kalimdor. It was Cairne Bloodhoof, chieftain of the Bloodhoof tribe, who ended that exile. When Warchief Thrall and his New Horde came to Mulgore during the Third War, their strength joined Cairne's own and together they broke the centaur and won the grasslands for the tauren at last. Upon the mesas Cairne raised a refuge open to every scattered tribe, and in time those tribes bent to his rule as one people, disagreeing sometimes on the path ahead but never on his wisdom to lead them.\n\nThe bluffs still bear the weight of that founding in their rises and bridges, in the tents of tribes gathered under one chieftain's roof.",
		source = "https://warcraft.wiki.gg/wiki/Thunder_Bluff",
	},
	[1457] = {
		name = "Darnassus",
		short = "The night elves built Darnassus after the Third War, when their long immortality had failed them. Many could not bear the sudden weight of aging and frailty.",
		full = "The night elves built Darnassus after the Third War, when their long immortality had failed them. Many could not bear the sudden weight of aging and frailty. A number of grieving druids resolved to plant a new World Tree to restore their bond with the eternal world. With Malfurion Stormrage gone missing, Fandral Staghelm took up the mantle of Archdruid and led the effort. The tree they raised, Teldrassil, rose off the coast until its crown broke above the clouds, and among its boughs the night elves founded their city as a testament to their people's survival.\n\nDarnassus stands open to the sky, unlike the close, walled cities of the humans and dwarves. It is built around a broad lake, its shores joined by graceful bridges, its pathways carpeted in fallen leaves. The Temple of the Moon rises above the trees as the seat of High Priestess Tyrande Whisperwind and her Sisters of Elune, beside the colonnaded Hall of Justice where the Sentinels keep their watch. The city remains what it was built to be: a tranquil refuge, and a monument to a people learning to live with mortality.",
		source = "https://warcraft.wiki.gg/wiki/Darnassus",
	},
	[1458] = {
		name = "Undercity",
		short = "Long before the Forsaken made it their own, the Undercity had a name and a purpose. Far beneath the palace of Lordaeron ran the ancient crypts of its royal dead, its dungeons, its sewers.",
		full = "Long before the Forsaken made it their own, the Undercity had a name and a purpose. Far beneath the palace of Lordaeron ran the ancient crypts of its royal dead, its dungeons, its sewers. It was meant only for prisoners and corpses, but the poorest of Lordaeron's people crowded down into the dark anyway, and the guards' sweeps to clear them out never held.\n\nWhen the Lich King's grip on his creations slipped, Sylvanas Windrunner broke from the Scourge with those undead who had kept their minds, and turned on Arthas, the fallen prince who had made her what she was. She lured him into a trap in the ruined kingdom; he escaped with Kel'Thuzad's help and fled north to become the Lich King himself. Sylvanas and her followers, left masters of the field, named themselves the Forsaken and claimed the crypts beneath the wrecked capital, finishing the stronghold the Scourge had begun.\n\nWhat stands now is a maze built for defense: rivers of poisonous sludge running through every avenue, the air thick with fumes the living can barely stand to breathe. For the Forsaken it is shelter in a world that still hunts them.",
		source = "https://warcraft.wiki.gg/wiki/Undercity",
	},
